 public function testLegacyAccessTokenAndReadOnlyBlueprintProvidersRemainSupportedThroughSignedGrants():void {
  global $wpdb;$id=$this->input['integration_id'];$wpdb->delete(Tables::integration_secrets(),['integration_id'=>$id,'secret_name'=>'personal_access_token']);self::assertTrue((new DigiForge\Integrations\Repository())->storeSecret($id,'access_token','offline-catalog-fixture-credential'));ScopedProviderConnectionFixture::approve($id,$this->owner);
  $input=$this->input;$input['requests']=[['kind'=>'blueprint','blueprint_id'=>101],['kind'=>'providers','blueprint_id'=>101]];$calls=[];
  $client=new DigiForge\POD\PrintifyCatalogClient(static function($url,$args)use(&$calls){$calls[]=$url;self::assertSame('Bearer offline-catalog-fixture-credential',$args['headers']['Authorization']);return ['response'=>['code'=>200],'body'=>str_contains($url,'print_providers')?'[{"id":2}]':'{"id":101,"title":"Synthetic blueprint"}'];});
  $r=new Reads($client);$grant=$r->approve($input,'legacy-secret');self::assertIsArray($grant);$this->unlocked();$blueprint=$r->read($grant['sha256'],0,'legacy-blueprint');$providers=$r->read($grant['sha256'],1,'legacy-providers');self::assertIsArray($blueprint);self::assertIsArray($providers);self::assertSame(101,$blueprint['data']['id']);self::assertSame([['id'=>2]],$providers['data']);self::assertCount(2,$calls);self::assertStringNotContainsString('offline-catalog-fixture-credential',wp_json_encode([$blueprint,$providers]));
 }
 public function testOwnerApprovalCannotReleaseSafetyLocksOrReadCredentials():void {
  self::assertTrue(class_exists(Reads::class),'Scoped catalog read repository must exist.');$calls=0;$r=new Reads($this->client($calls));$grant=$r->approve($this->input,'grant-locked');self::assertIsArray($grant);self::assertSame('printify.catalog.read',$grant['grant']['capability']);$read=$r->read($grant['sha256'],0,'request-locked');self::assertWPError($read);self::assertSame('catalog_read_safety_locked',$read->get_error_code());self::assertSame(0,$calls);self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertFalse(DigiForge\Core\Settings::is_enabled('printify'));
 }
 public function testExactReadPersistsDraftEvidenceAndRejectsReplayCrossAccountRevocationAndTampering():void {
  self::assertTrue(class_exists(Reads::class));$calls=0;$r=new Reads($this->client($calls));$grant=$r->approve($this->input,'grant-functional');self::assertIsArray($grant);$this->unlocked();self::assertFalse(DigiForge\Core\Settings::is_enabled('printify'));
  $subscriber=self::factory()->user->create(['role'=>'subscriber']);wp_set_current_user($subscriber);self::assertWPError($r->read($grant['sha256'],0,'cross-account'));wp_set_current_user($this->owner);
